"""Build per-family human-review packets (stats + seeded random sample + checklist).

The packet is what a real reviewer reads before signing. This tool never approves anything.
"""
import hashlib
import json
import random
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]
MAN = REPO / "data/specialists/manifests"
OUT = REPO / "docs/review/packets"
SAMPLE = 25
CHECK = [
    "Content is original (written/generated by the project) or its license permits training: ____",
    "No personal data, secrets, real names or contact details: ____",
    "No third-party copyrighted text/code/images/audio copied: ____",
    "Samples are factually correct and labels match content: ____",
    "No harmful operational instructions in ALLOW/chat answers: ____",
    "Audio only: voices are synthetic or every speaker consented: ____",
    "Reviewer name / role / date / signature: ____",
]


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    for src in sorted(MAN.glob("*/source.jsonl")):
        model = src.parent.name
        rows = [json.loads(l) for l in src.read_text(encoding="utf-8").splitlines() if l.strip()]
        rnd = random.Random(f"review-{model}")
        pick = rnd.sample(rows, min(SAMPLE, len(rows)))
        sha = hashlib.sha256(src.read_bytes()).hexdigest()
        lines = [f"# Human review packet — {model.upper()}", "",
                 f"- source.jsonl sha256: `{sha}`", f"- records: {len(rows)}", f"- groups: {len({r.get('group_id') for r in rows})}",
                 "- origin: synthetic / Claude-drafted at the owner's request (not real-world data)", "",
                 "## Checklist (reviewer fills in; unreviewed = NOT approved)", ""]
        lines += [f"- [ ] {c}" for c in CHECK]
        lines += ["", f"## Random sample ({len(pick)} of {len(rows)}, seeded, reproducible)", ""]
        for r in pick:
            body = {k: v for k, v in r.items() if k not in ("boxes",)}
            lines.append("```json\n" + json.dumps(body, ensure_ascii=False)[:700] + "\n```")
        (OUT / f"{model}.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
        print(model, len(rows))


if __name__ == "__main__":
    main()
